def _chave_empresa(razao_social, prospecto_id):
    texto = unicodedata.normalize("NFKD", str(razao_social or ""))
    texto = "".join(
        caractere for caractere in texto
        if not unicodedata.combining(caractere)
    )
    normalizado = " ".join(texto.casefold().strip().split())
    if not normalizado:
        normalizado = f"sem-nome:{prospecto_id}"
    return hashlib.sha256(normalizado.encode("utf-8")).hexdigest()


def separar_empresas_e_contatos(apps, schema_editor):
    EmpresaProspecto = apps.get_model("comercial", "EmpresaProspecto")
    Prospecto = apps.get_model("comercial", "Prospecto")
    ProspeccaoComercial = apps.get_model("comercial", "ProspeccaoComercial")
    alias = schema_editor.connection.alias
    campos_empresa = (
        "razao_social", "nome_fantasia", "cnpj", "site", "segmento", "cidade",
        "uf", "endereco", "cep", "origem", "observacoes",
    )
    empresas_por_chave = {}
    contatos = []

    queryset = Prospecto.objects.using(alias).all().order_by("criado_em", "pk")
    for contato in queryset.iterator(chunk_size=1000):
        chave = _chave_empresa(contato.razao_social, contato.pk)
        empresa = empresas_por_chave.get(chave)
        if empresa is None:
            empresa = EmpresaProspecto(
                chave_agrupamento=chave,
                **{campo: getattr(contato, campo) or "" for campo in campos_empresa},
            )
            empresas_por_chave[chave] = empresa
        else:
            for campo in campos_empresa:
                if not getattr(empresa, campo) and getattr(contato, campo):
                    setattr(empresa, campo, getattr(contato, campo))
        contatos.append((contato, chave))

    EmpresaProspecto.objects.using(alias).bulk_create(
        list(empresas_por_chave.values()), batch_size=500
    )
    for contato, chave in contatos:
        contato.empresa_id = empresas_por_chave[chave].pk
    Prospecto.objects.using(alias).bulk_update(
        [contato for contato, _ in contatos], ["empresa"], batch_size=1000
    )

    empresa_por_contato = {
        contato.pk: contato.empresa_id for contato, _ in contatos
    }
    prospeccoes = []
    for prospeccao in ProspeccaoComercial.objects.using(alias).exclude(
        prospecto_id__isnull=True
    ).iterator(chunk_size=500):
        prospeccao.empresa_prospecto_id = empresa_por_contato.get(
            prospeccao.prospecto_id
        )
        if prospeccao.empresa_prospecto_id:
            prospeccoes.append(prospeccao)
    ProspeccaoComercial.objects.using(alias).bulk_update(
        prospeccoes, ["empresa_prospecto"], batch_size=500
    )


def desfazer_separacao(apps, schema_editor):
    EmpresaProspecto = apps.get_model("comercial", "EmpresaProspecto")
    Prospecto = apps.get_model("comercial", "Prospecto")
    ProspeccaoComercial = apps.get_model("comercial", "ProspeccaoComercial")
    alias = schema_editor.connection.alias
    ProspeccaoComercial.objects.using(alias).update(empresa_prospecto=None)
    Prospecto.objects.using(alias).update(empresa=None)
    EmpresaProspecto.objects.using(alias).all().delete()


